pub(crate) fn sv_nl_root(v: &SvRat) -> Option<SvRat> {
    if v.num < 0 { return None; }
    let n = match sv_nl_isqrt(v.num) { Some(__nikaia_value) => __nikaia_value, None => return None };
    let d = match sv_nl_isqrt(v.den) { Some(__nikaia_value) => __nikaia_value, None => return None };
    sv_rat(n, d)
}

pub(crate) fn sv_nl_isqrt(n: i64) -> Option<i64> {
    let mut r: i64 = 0;
    while r <= 3037000499i64 && unsafe { nikaia_std::proven::mul::<i64>(r, r) } < n {
        r = unsafe { nikaia_std::proven::add::<i64>(r, 1) };
        if r > 100000 { return None; }
    }
    if r * r == n { Some(r) } else { None }
}

pub(crate) fn sv_nl_candidates(defs: &[SvNl], values: &collections::BTreeMap<String, SvRat>) -> Vec<SvLemma> {
    let mut out: Vec<SvLemma> = vec![];
    for i in 0..defs.len() as i64 {
        let t = (*unsafe { nikaia_std::proven::read(&defs, (i) as usize) }).clone();
        let a = sv_real_named(values, &t.a);
        let b = sv_real_named(values, &t.b);
        for j in 0..defs.len() as i64 {
            if j != i && unsafe { nikaia_std::proven::read(&defs, (j) as usize) }.op == t.op {
                let mut c = sv_lemma(String::from("congruence"), i);
                c.other = j;
                out.push(c.clone());
                if t.op == "*" || t.op == "pow2" {
                    let mut mono = sv_lemma(if t.op == "*" { String::from("mono") } else { String::from("pow2-mono") }, i);
                    mono.other = j;
                    out.push(mono);
                }
            }
        }
        if t.op == "*" {
            out.push(sv_lemma(String::from("square"), i));
            for k in 0..3 {
                let mut z = sv_lemma(String::from("zero"), i);
                z.sa = k;
                out.push(z);
            }
            for sa in [1, -1] {
                for sb in [1, -1] {
                    let mut sg = sv_lemma(String::from("sign"), i);
                    sg.sa = sa;
                    sg.sb = sb;
                    out.push(sg);
                    let mut tg = sv_lemma(String::from("tangent"), i);
                    tg.sa = sa;
                    tg.sb = sb;
                    tg.a = a.clone();
                    tg.b = b.clone();
                    out.push(tg);
                }
            }
            for k in 1..3 {
                let mut pt = sv_lemma(String::from("point"), i);
                pt.sa = k;
                pt.a = if k == 1 { a.clone() } else { b.clone() };
                out.push(pt);
            }
        } else if t.op == "/" {
            let mut dp = sv_lemma(String::from("divpoint"), i);
            dp.b = b.clone();
            out.push(dp);
        } else if t.op == "div" || t.op == "mod" {
            let mut dv = sv_lemma(String::from("division"), i);
            dv.b = b.clone();
            out.push(dv);
        } else {
            out.push(sv_lemma(String::from("pow2-neg"), i));
            out.push(sv_lemma(String::from("pow2-low"), i));
            out.push(sv_lemma(String::from("pow2-pos"), i));
            let mut pp = sv_lemma(String::from("pow2-point"), i);
            pp.a = a.clone();
            out.push(pp);
        }
    }
    out
}

#[cfg(test)]
pub(crate) fn sv_nl_test_lemmas(source: &str) -> String {
    let mut reals: collections::BTreeSet<String> = collections::BTreeSet::new();
    let mut defs: Vec<SvNl> = vec![];
    let script = match sv_smtlib_script(source) {
        SvSmtRead::Script(ref s, ref sorts) => {
            reals = sorts.reals.copy_owned();
            defs = sorts.nl.copy_owned();
            s.clone()
        },
        SvSmtRead::Failed(_) => { return String::from(""); },
    };
    let mut arena = script.arena.clone();
    let goal = arena.boolean(false);
    let nl = match sv_nl_engine(&arena, &script.assertions, goal, &lg_budget(), "both", &reals, "", &defs) { Some(__nikaia_value) => __nikaia_value, None => return String::from("") };
    let mut names: Vec<String> = nikaia_std::block::list(nikaia_std::block::Place::Block);
    for l in nl.lemmas.iter() { names.push(nikaia_std::block::Text::from(l.schema.to_string())); }
    let out = format!("; lemmas [{}]", nikaia_std::block::Text::from(names.join(", ")));
    let steps = match nl.run.driven {
        SvDriven::Proved(_, ref s) => s.copy_owned(),
        _ => { return out; },
    };
    let mut changed = nl.lemmas.copy_owned();
    for i in 0..changed.len() as i64 {
        let s = nikaia_std::block::Text::from(nikaia_std::index::get(&changed, (i) as usize).schema.to_string());
        if s == "point" || s == "tangent" || s == "pow2-point" { (*unsafe { nikaia_std::proven::slot(&mut changed, (i) as usize) }).a = match sv_rat_add(&unsafe { nikaia_std::proven::read(&changed, (i) as usize) }.a, &sv_int(1)) { Some(__nikaia_value) => __nikaia_value, None => return out }; } else if s == "divpoint" || s == "division" { (*unsafe { nikaia_std::proven::slot(&mut changed, (i) as usize) }).b = match sv_rat_add(&unsafe { nikaia_std::proven::read(&changed, (i) as usize) }.b, &sv_int(1)) { Some(__nikaia_value) => __nikaia_value, None => return out }; } else { continue; }
        let verdict = match sv_lemma_check(&arena, &script.assertions, goal, &reals, &defs, &changed, &steps) {
            None => "refused (not an instance)",
            Some(ref v) => if v.ok { "accepted" } else { "refused" },
        };
        return format!("{}; changed {}: {}", out, s, verdict);
    }
    out
}

